use super::{FontStyle, Glyph, Metrics};
use std::{cell::RefCell, collections::HashMap, rc::Rc};

/// Generated by tools/gen_font.py (format documented there).
static DATA: &[u8] = include_bytes!("../../../assets/readitor-fonts.bin");

/// Extra contrast applied to coverage. 1.0 = linear; <1.0 darkens/thickens text slightly,
/// compensating for naive sRGB-space blending (no gamma-correct blend yet).
const COVERAGE_GAMMA: f32 = 0.82;

struct Rec {
    cp: u32,
    advance: f32,
    left: i32,
    top: i32,
    w: usize,
    h: usize,
    off: usize,
}

struct Face {
    ascent: f32,
    descent: f32,
    recs: Vec<Rec>, // sorted by cp
    data: &'static [u8],
}

pub struct FontSystem {
    src_em: f32,
    faces: Vec<Face>,
    cache: RefCell<GlyphCache>,
}

/// Key for the rasterized-glyph cache: face index, char, and pixel size in 1/16 px.
type CacheKey = (u8, char, u32);
/// Memoized glyph rasterizations; `None` marks blank glyphs (e.g. space).
type GlyphCache = HashMap<CacheKey, Option<Rc<Glyph>>>;

struct Reader {
    b: &'static [u8],
    p: usize,
}

impl Reader {
    fn take(&mut self, n: usize) -> &'static [u8] {
        let s = &self.b[self.p..self.p + n];
        self.p += n;
        s
    }
    fn u16(&mut self) -> u16 {
        u16::from_le_bytes(self.take(2).try_into().unwrap())
    }
    fn i16(&mut self) -> i16 {
        i16::from_le_bytes(self.take(2).try_into().unwrap())
    }
    fn u32(&mut self) -> u32 {
        u32::from_le_bytes(self.take(4).try_into().unwrap())
    }
    fn f32(&mut self) -> f32 {
        f32::from_le_bytes(self.take(4).try_into().unwrap())
    }
}

impl FontSystem {
    /// Parse the embedded atlas. The data is build-time trusted, so malformed input panics (caught by tests).
    pub fn load_embedded() -> Self {
        let mut r = Reader { b: DATA, p: 0 };
        assert_eq!(r.take(4), b"RFNT", "bad font atlas magic");
        assert_eq!(r.u32(), 1, "unsupported font atlas version");
        let src_em = r.u16() as f32;
        let nfaces = r.u16() as usize;
        let mut faces = Vec::with_capacity(nfaces);
        for _ in 0..nfaces {
            let ascent = r.f32();
            let descent = r.f32();
            let n = r.u32() as usize;
            let mut recs = Vec::with_capacity(n);
            for _ in 0..n {
                recs.push(Rec {
                    cp: r.u32(),
                    advance: r.f32(),
                    left: r.i16() as i32,
                    top: r.i16() as i32,
                    w: r.u16() as usize,
                    h: r.u16() as usize,
                    off: r.u32() as usize,
                });
            }
            let len = r.u32() as usize;
            let data = r.take(len);
            faces.push(Face {
                ascent,
                descent,
                recs,
                data,
            });
        }
        Self {
            src_em,
            faces,
            cache: RefCell::new(HashMap::new()),
        }
    }

    fn rec(&self, style: FontStyle, ch: char) -> Option<(&Face, &Rec)> {
        let face = &self.faces[style.index()];
        let find = |c: char| {
            face.recs
                .binary_search_by_key(&(c as u32), |r| r.cp)
                .ok()
                .map(|i| &face.recs[i])
        };
        find(ch)
            .or_else(|| find('\u{FFFD}'))
            .or_else(|| find('?'))
            .map(|r| (face, r))
    }

    pub fn metrics(&self, style: FontStyle, size: f32) -> Metrics {
        let f = &self.faces[style.index()];
        let s = size / self.src_em;
        Metrics {
            ascent: f.ascent * s,
            descent: f.descent * s,
        }
    }

    pub fn advance(&self, style: FontStyle, ch: char, size: f32) -> f32 {
        self.rec(style, ch)
            .map_or(0.0, |(_, r)| r.advance * size / self.src_em)
    }

    pub fn measure(&self, style: FontStyle, text: &str, size: f32) -> f32 {
        text.chars().map(|c| self.advance(style, c, size)).sum()
    }

    /// Rasterized glyph at `size` px (cached). `None` for blank glyphs (e.g. space).
    pub fn glyph(&self, style: FontStyle, ch: char, size: f32) -> Option<Rc<Glyph>> {
        let key = (style.index() as u8, ch, (size * 16.0).round() as u32);
        if let Some(g) = self.cache.borrow().get(&key) {
            return g.clone();
        }
        let g = self.rec(style, ch).and_then(|(face, r)| {
            if r.w == 0 || r.h == 0 {
                return None;
            }
            let src = &face.data[r.off..r.off + r.w * r.h];
            Some(Rc::new(rescale(src, r, size / self.src_em)))
        });
        self.cache.borrow_mut().insert(key, g.clone());
        g
    }
}

/// Resample a source-size glyph to scale `s`. Downscale: exact area average (box filter).
/// Upscale: bilinear.
fn rescale(src: &[u8], r: &Rec, s: f32) -> Glyph {
    let (sw, sh) = (r.w as i32, r.h as i32);
    // Source glyph box in baseline space (x right, y down): x in [left, left+sw), y in [-top, -top+sh).
    let dx0 = (r.left as f32 * s).floor() as i32;
    let dx1 = ((r.left + sw) as f32 * s).ceil() as i32;
    let dy0 = (-r.top as f32 * s).floor() as i32;
    let dy1 = ((-r.top + sh) as f32 * s).ceil() as i32;
    let (dw, dh) = ((dx1 - dx0).max(1) as usize, (dy1 - dy0).max(1) as usize);
    let at = |x: i32, y: i32| -> f32 {
        if x < 0 || y < 0 || x >= sw || y >= sh {
            0.0
        } else {
            src[(y * sw + x) as usize] as f32
        }
    };
    let mut cov = vec![0u8; dw * dh];
    for j in 0..dh {
        for i in 0..dw {
            let v = if s >= 1.0 {
                let fx = (dx0 + i as i32) as f32 + 0.5;
                let fy = (dy0 + j as i32) as f32 + 0.5;
                let sx = fx / s - r.left as f32 - 0.5;
                let sy = fy / s + r.top as f32 - 0.5;
                let (x0, y0) = (sx.floor() as i32, sy.floor() as i32);
                let (tx, ty) = (sx - x0 as f32, sy - y0 as f32);
                (at(x0, y0) * (1.0 - tx) + at(x0 + 1, y0) * tx) * (1.0 - ty)
                    + (at(x0, y0 + 1) * (1.0 - tx) + at(x0 + 1, y0 + 1) * tx) * ty
            } else {
                let x0 = (dx0 + i as i32) as f32 / s - r.left as f32;
                let x1 = (dx0 + i as i32 + 1) as f32 / s - r.left as f32;
                let y0 = (dy0 + j as i32) as f32 / s + r.top as f32;
                let y1 = (dy0 + j as i32 + 1) as f32 / s + r.top as f32;
                let mut acc = 0.0;
                for iy in (y0.floor().max(0.0) as i32)..(y1.ceil().min(sh as f32) as i32) {
                    let wy = (y1.min(iy as f32 + 1.0) - y0.max(iy as f32)).max(0.0);
                    for ix in (x0.floor().max(0.0) as i32)..(x1.ceil().min(sw as f32) as i32) {
                        let wx = (x1.min(ix as f32 + 1.0) - x0.max(ix as f32)).max(0.0);
                        acc += wx * wy * at(ix, iy);
                    }
                }
                acc / ((x1 - x0) * (y1 - y0))
            };
            let n = (v / 255.0).clamp(0.0, 1.0).powf(COVERAGE_GAMMA);
            cov[j * dw + i] = (n * 255.0 + 0.5) as u8;
        }
    }
    Glyph {
        width: dw,
        height: dh,
        left: dx0,
        top: -dy0,
        coverage: cov,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn loads_and_measures() {
        let f = FontSystem::load_embedded();
        let w = f.measure(FontStyle::Regular, "Hello", 16.0);
        assert!(w > 20.0 && w < 60.0, "unexpected width {w}");
        // monospace: all advances equal
        let a = f.advance(FontStyle::Mono, 'i', 16.0);
        let b = f.advance(FontStyle::Mono, 'W', 16.0);
        assert!((a - b).abs() < 0.01);
        // space is blank, 'A' is not
        assert!(f.glyph(FontStyle::Regular, ' ', 16.0).is_none());
        let g = f.glyph(FontStyle::Regular, 'A', 16.0).unwrap();
        assert!(g.coverage.iter().any(|&c| c > 200));
        // unknown glyph falls back instead of vanishing
        assert!(f.advance(FontStyle::Regular, '\u{4E2D}', 16.0) > 0.0);
    }
}
